using System.ComponentModel;
using System.Net;
using System.Text.Json;
using Microsoft.Extensions.AI;

// --- Tool implementations --------------------------------------------------------

/// <summary>Tools exposed to the AI agent during research.</summary>
static class ResearchTools
{
    private static readonly List<(string Topic, string Content)> _notes = [];

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  🔍  Searching: \"{query}\"");
        Console.ResetColor();

        // Use DuckDuckGo's instant-answer API (no key required).
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            // Abstract / main answer
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add(text);
                }
            }

            if (results.Count == 0)
                return "No results found. Try rephrasing your query.";

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Save a research note under a topic heading for later reference.")]
    public static string SaveNote(
        [Description("Short topic label for the note")] string topic,
        [Description("The note content to save")] string content)
    {
        _notes.Add((topic, content));

        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  📝  Note saved under \"{topic}\" ({content.Length} chars)");
        Console.ResetColor();

        return $"Note saved under \"{topic}\".";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Topic} ---\n{n.Content}"));
    }
}

// --- Agent loop ------------------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
var model  = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable to run this agent.");
    Console.Error.WriteLine("Optionally set OPENAI_MODEL (default: gpt-4o-mini).");
    return 1;
}

IChatClient client = new ChatClientBuilder(
        new OpenAI.OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var tools = new AITool[]
{
    AIFunctionFactory.Create(ResearchTools.SearchWeb),
    AIFunctionFactory.Create(ResearchTools.SaveNote),
    AIFunctionFactory.Create(ResearchTools.GetNotes),
};

Console.WriteLine("╔═══════════════════════════════════════════╗");
Console.WriteLine("║        🔬  AI Research Agent  🔬         ║");
Console.WriteLine("╠═══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.   ║");
Console.WriteLine("╚═══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("Research topic ▸ ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    var systemPrompt = """
        You are a research agent. Given a topic, you:
        1. Search the web multiple times with different queries to gather information.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes and produce a
           well-structured summary with key facts, organized under headings.
        Be thorough — perform at least 2-3 searches with varied queries before summarizing.
        """;

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
    };

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Agent is researching…");
    Console.ResetColor();

    var response = await client.GetResponseAsync(messages, new()
    {
        Tools = [.. tools],
    });

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine("═══ Research Summary ═══");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");
return 0;

